python3 -c "
import pathlib
p = pathlib.Path('tests/codegen/io/streams.rs')
t = p.read_text()
NEW = '''

/// Verifies an options array that arrives as a boxed \`Mixed\` value is judged like a literal one.
///
/// Kimi K3 asked, auditing this branch, whether a statically-\`Mixed\` empty indexed options array
/// could revive the segfault the previous fix killed. It cannot — but the probe exposed two
/// adjacent bugs, and both are pinned here. A runtime-built map reaches these builtins boxed:
/// the shape guard read the BOX's header instead of the array's, and it compared entry values
/// against the container tags without unboxing them.
///
/// MEASURED on \`php -n\` 8.5.6, all three shapes.
#[test]
fn test_stream_context_options_arriving_as_a_boxed_mixed_value() {
    let out = compile_and_run(
        r#\"<?php
\\\$empty = json_decode(\"[]\", true);
\\\$c = stream_context_create(\\\$empty);
stream_context_set_option(\\\$c, \"http\", \"method\", \"POST\");
echo json_encode(stream_context_get_options(\\\$c)), \"|\";
\\\$map = json_decode(\"{\\\\\"http\\\\\":{\\\\\"method\\\\\":\\\\\"GET\\\\\"}}\", true);
echo json_encode(stream_context_get_options(stream_context_create(\\\$map))), \"|\";
\\\$list = json_decode(\"[1]\", true);
try { stream_context_create(\\\$list); } catch (Throwable \\\$t) { echo get_class(\\\$t); }
\"#,
    );
    assert_eq!(
        out,
        \"{\\\\\"http\\\\\":{\\\\\"method\\\\\":\\\\\"POST\\\\\"}}|{\\\\\"http\\\\\":{\\\\\"method\\\\\":\\\\\"GET\\\\\"}}|ValueError\"
    );
}
'''
p.write_text(t.rstrip() + '\n' + NEW)
print('test added')
